import{_ as o,a0 as l,w as i,s,ao as u,I as t,x as e,a1 as a,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用n2n配置二層點對點VPN | LCTT x X-CMD","titleTemplate":false,"description":"使用n2n配置二層點對點VPN | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用n2n配置二層點對點VPN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用n2n配置二層點對點VPN | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141021 Configuring layer-two peer-to-peer VPN using n2n","title":"使用n2n配置二層點對點VPN","tag":"201412","desc":""},"relativePath":"201412/20141021 Configuring layer-two peer-to-peer VPN using n2n.md","filePath":"[post].md"}'),d={name:"201412/20141021 Configuring layer-two peer-to-peer VPN using n2n.md"};function g(P,n,m,f,b,h){const r=l("Link");return i(),s("div",null,[n[16]||(n[16]=u(`<h1 id="使用n2n配置二層點對點vpn" tabindex="-1">使用n2n配置二層點對點VPN <a class="header-anchor" href="#使用n2n配置二層點對點vpn" aria-label="Permalink to “使用n2n配置二層點對點VPN”">​</a></h1><p>n2n是一個二層點對點虛擬專用網（VPN），它允許用户在網絡層面而非應用層面開發典型的P2P應用功能。這就意味着，用户可以獲得本地IP可見性（如，屬於同一個n2n網絡的兩台PC可以互相ping通），以及不管他們現在身處哪個網絡，只要有相同的網絡IP地址就可以訪問到。簡言之，就像OpenVPN將SSL從應用（如，用於部署https協議）搬到了網絡協議一樣，n2n將P2P從應用搬到了網絡層面。</p><h3 id="n2n主要功能" tabindex="-1">n2n主要功能 <a class="header-anchor" href="#n2n主要功能" aria-label="Permalink to “n2n主要功能”">​</a></h3><p>n2n是一個基於P2P協議的加密的二層專用網。</p><p>加密使用開放協議部署在邊緣節點，它使用用户定義的加密鑰匙：你自己控制安全，而不用授權給公司，而Skype或Hamachi卻是要的。</p><p>各個n2n用户可以同時屬於多個網絡（或者社區）。</p><p>它擁有在反向通信方向（如，從外部到內部）穿越NAT和防火牆的能力，因此可以到達n2n節點，即使運行在一個專用網中。防火牆不再是IP層面掌控通信的障礙。</p><p>n2n網絡並不意味着它是獨立的，它可以在n2n和非n2n網絡間路由通信。</p><h3 id="n2n架構基於兩個組件" tabindex="-1">n2n架構基於兩個組件 <a class="header-anchor" href="#n2n架構基於兩個組件" aria-label="Permalink to “n2n架構基於兩個組件”">​</a></h3><p><strong>超級節點</strong>：它在啓動時用於邊緣節點或用於達到對稱防火牆後面的節點。對於這些節點，該應用主要是一個目錄暫存器和包路由器，而不是直接通信。</p><p><strong>邊緣節點</strong>：安裝在用户PC的應用程序，它允許構建n2n網絡。實際上，各個邊緣節點創建一個tun/tap設備，該設備是n2n網絡的進入點。</p><h3 id="安裝n2n到ubuntu" tabindex="-1">安裝n2n到Ubuntu <a class="header-anchor" href="#安裝n2n到ubuntu" aria-label="Permalink to “安裝n2n到Ubuntu”">​</a></h3><p>打開終端並運行以下命令</p><pre><code>$ sudo apt-get install subversion build-essential libssl-dev
$ svn co https://svn.ntop.org/svn/ntop/trunk/n2n
$ cd n2n/n2n_v2
$ make
$ sudo make install
</code></pre><h3 id="使用n2n配置p2p-vpn" tabindex="-1">使用n2n配置P2P VPN <a class="header-anchor" href="#使用n2n配置p2p-vpn" aria-label="Permalink to “使用n2n配置P2P VPN”">​</a></h3><p>首先，我們需要配置一個超級節點和任意數量的邊緣節點。</p><p>決定將超級節點放在哪個地方。假設你將它放到了主機a.b.c.d的xyw端口上。</p><p>決定使用何種密碼加密來保證數據安全。假設你使用密碼encryptme。</p><p>決定你想要使用的網絡名稱。假設你將它命名為mynetwork。注意，你可以使用超級節點/邊緣節點來處理多個網絡，不僅僅只有一個哦。</p><p>決定在邊緣節點上使用什麼IP地址。假設你使用10.1.2.0/24。</p><p>啓動應用：</p><h3 id="配置超級節點" tabindex="-1">配置超級節點 <a class="header-anchor" href="#配置超級節點" aria-label="Permalink to “配置超級節點”">​</a></h3><pre><code>supernode -l xyw
</code></pre><h3 id="配置邊緣節點" tabindex="-1">配置邊緣節點 <a class="header-anchor" href="#配置邊緣節點" aria-label="Permalink to “配置邊緣節點”">​</a></h3><p>在各個邊緣節點，使用以下命令來連接到P2P VPN。</p><pre><code>sudo edge -a 10.1.2.1 -c mynetwork -k encryptme -l a.b.c.d:xyw

sudo edge -a 10.1.2.2 -c mynetwork -k encryptme -l a.b.c.d:xyw
</code></pre><h3 id="現在來測試你的n2n網絡" tabindex="-1">現在來測試你的n2n網絡 <a class="header-anchor" href="#現在來測試你的n2n網絡" aria-label="Permalink to “現在來測試你的n2n網絡”">​</a></h3><pre><code>edge node1&gt; ping 10.1.2.2

edge node2&gt; ping 10.1.2.1
</code></pre><p>Windows n2n VPN客户端（N2N邊緣圖形界面）</p>`,29)),t("p",null,[n[1]||(n[1]=e("你可以從",-1)),a(r,{href:"http://sourceforge.net/projects/n2nedgegui/"},{default:p(()=>[...n[0]||(n[0]=[e("這裏",-1)])]),_:1}),n[2]||(n[2]=e("下載N2N邊緣圖形界面。",-1))]),n[17]||(n[17]=t("p",null,"N2N邊緣圖形界面是一個基本的安裝器和用於點對點‘n2n VPN解決方案’的GUI配置界面。",-1)),n[18]||(n[18]=t("p",null,[t("img",{src:"http://www.ubuntugeek.com/wp-content/uploads/2014/10/client.jpg",alt:""})],-1)),n[19]||(n[19]=t("hr",null,null,-1)),t("p",null,[n[4]||(n[4]=e("via: ",-1)),a(r,{href:"http://www.ubuntugeek.com/configuring-layer-two-peer-to-peer-vpn-using-n2n.html"},{default:p(()=>[...n[3]||(n[3]=[e("http://www.ubuntugeek.com/configuring-layer-two-peer-to-peer-vpn-using-n2n.html",-1)])]),_:1})]),t("p",null,[n[8]||(n[8]=e("作者：",-1)),a(r,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:p(()=>[...n[5]||(n[5]=[e("ruchi",-1)])]),_:1}),n[9]||(n[9]=e(" 譯者：",-1)),a(r,{href:"https://github.com/GOLinux"},{default:p(()=>[...n[6]||(n[6]=[e("GOLinux",-1)])]),_:1}),n[10]||(n[10]=e(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:p(()=>[...n[7]||(n[7]=[e("wxy",-1)])]),_:1})]),t("p",null,[n[13]||(n[13]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[11]||(n[11]=[e("LCTT",-1)])]),_:1}),n[14]||(n[14]=e(" 原創翻譯，",-1)),a(r,{href:"http://linux.cn/"},{default:p(()=>[...n[12]||(n[12]=[e("Linux中國",-1)])]),_:1}),n[15]||(n[15]=e(" 榮譽推出",-1))])])}const T=o(d,[["render",g]]);export{x as __pageData,T as default};
